-			return fmt.Errorf("opencode export timed out after %s", openCodeCommandTimeout)
-		}
-		return fmt.Errorf("opencode export failed: %w (stderr: %s)", err, strings.TrimSpace(stderr.String()))
+	if runErr := cmd.Run(); runErr != nil {
