	cmd.Stderr = &stderr
	if runErr := cmd.Run(); runErr != nil {
		return classifyOpenCodeExportError(ctx, runErr, stderr.String(), sessionID)
	}

	if syncErr := file.Sync(); syncErr != nil {
		return fmt.Errorf("failed to flush export file: %w", syncErr)
	}

	return nil
}

