// unprobedFetcherHint names the registered agents that can materialize a
// transcript on demand but were not asked to during auto-detection, so a user
// who named the wrong agent learns the one-flag fix — as a command to paste,
// not a fix to assemble. Returns "" when the only such agent is the one already
// tried.
func unprobedFetcherHint(tried types.AgentName, sessionID string) string {
	var names []string
	for _, name := range agent.List() {
		if name == tried {
			continue
		}
		ag, err := agent.Get(name)
		if err != nil {
			continue
		}
		if _, ok := agent.AsTranscriptFetcher(ag); ok {
			names = append(names, string(name))
		}
	}
	if len(names) == 0 {
		return ""
	}
	return fmt.Sprintf("\nHint: %s can export transcripts on demand:\n  entire session attach %s --agent %s",
		strings.Join(names, " and "), sessionID, names[0])
}
